use lean_runtime::semantics::hash;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &(String, usize), n: u64) -> u64 {
    let sl = &inp.0.as_bytes()[inp.1..];
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(acc, hash::slice_hash(black_box(sl)));
    }
    acc
}

fn main() {
    run(
        || {
            let s = mixed();
            let a = s.char_indices().nth(3).unwrap().0;
            (s, a)
        },
        kernel,
    )
}
